interface LogoProps {
  /** Rendered width/height in CSS pixels. */
  size?: number
  /** Decorative when the brand name is already written next to it. */
  decorative?: boolean
  className?: string
}

/**
 * The iConnecto app logo (generated by scripts/generate_icons.py from design/logo-source.png).
 * Fixed width/height prevent layout shift while the image loads.
 */
export function Logo({ size = 40, decorative = false, className = '' }: LogoProps) {
  // The 96px asset stays crisp up to ~48 CSS px on 2x screens; larger sizes use the 192px asset.
  const src = size <= 48 ? '/icons/icon-96.png' : '/icons/icon-192.png'
  return (
    <img
      src={src}
      width={size}
      height={size}
      alt={decorative ? '' : 'iConnecto'}
      aria-hidden={decorative || undefined}
      draggable={false}
      className={`logo ${className}`.trim()}
    />
  )
}
